// Simulador de planificación. Cada proceso: nombre, llegada y ráfaga (unidades de tiempo de CPU).
function simular(procesos, quantum, costo = 0, detalle = true) {
  const n = procesos.length;
  const resto = procesos.map(p => p.rafaga);
  const primera = Array(n).fill(null), fin = Array(n).fill(null);
  const orden = [...procesos.keys()].sort((a, b) => procesos[a].llegada - procesos[b].llegada);
  const cola = [];
  let t = 0, sig = 0, ultimo = -1, cambios = 0, gantt = '';
  const admitir = () => { while (sig < n && procesos[orden[sig]].llegada <= t) cola.push(orden[sig++]); };
  admitir();
  while (cola.length || sig < n) {
    if (!cola.length) { t = procesos[orden[sig]].llegada; admitir(); continue; }
    const i = cola.shift();
    if (ultimo !== -1 && ultimo !== i) { cambios++; t += costo; }   // cambio de contexto
    if (primera[i] === null) primera[i] = t;
    const corre = Math.min(quantum, resto[i]);
    gantt += `[${procesos[i].nombre} ${t}-${t + corre}]`;
    t += corre; resto[i] -= corre; ultimo = i;
    admitir();                      // los que llegaron mientras corría entran antes que el que vuelve
    if (resto[i] > 0) cola.push(i); else fin[i] = t;
  }
  const espera = procesos.map((p, i) => fin[i] - p.llegada - p.rafaga);
  const respuesta = procesos.map((p, i) => primera[i] - p.llegada);
  const prom = v => (v.reduce((a, b) => a + b, 0) / v.length).toFixed(2);
  const nombre = quantum === Infinity ? 'FIFO      ' : 'Quantum ' + quantum + '  ';
  if (detalle) console.log(nombre + gantt);
  console.log(nombre + '| espera prom. ' + prom(espera) + ' | respuesta prom. ' + prom(respuesta) +
              ' | cambios ' + cambios + ' | termina en t=' + t);
}

const camiones = [
  { nombre: 'A', llegada: 0, rafaga: 8 },
  { nombre: 'B', llegada: 1, rafaga: 2 },
  { nombre: 'C', llegada: 2, rafaga: 3 },
];
console.log('--- cambiar de contexto sin costo ---');
for (const q of [Infinity, 4, 2, 1]) simular(camiones, q);
console.log('--- cada cambio de contexto cuesta 0,5 ---');
for (const q of [Infinity, 4, 2, 1]) simular(camiones, q, 0.5, false);

#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <unistd.h>

static double t(clockid_t c) { struct timespec s; clock_gettime(c, &s); return s.tv_sec + s.tv_nsec / 1e9; }

int main(int argc, char **argv) {
  double seg = atof(argv[1]); const char *nombre = argv[2];
  double fin = t(CLOCK_MONOTONIC) + seg; volatile unsigned long x = 0;
  while (t(CLOCK_MONOTONIC) < fin) { for (int i = 0; i < 100000; i++) x += i; }   // cálculo puro
  printf("%-10s nice=%2d  CPU usada: %.2f s de %.0f s\n", nombre, nice(0), t(CLOCK_PROCESS_CPUTIME_ID), seg);
  return 0;
}
